  "REVISI ORDER: kalau lead sudah order lalu ingin mengubah (COD <-> transfer, alamat, paket), kirim ringkasan baru dan minta konfirmasi, lalu panggil buat_order lagi dengan data lengkap terbaru. Sistem akan merevisi order yang sama (bukan order baru). Setelah revisi berhasil pakai template sesuai pembayaran barunya.";

// Susun konteks untuk Claude dari payload webhook Wablas + baris leads_context.
// Mengembalikan null kalau bot harus diam (lead sedang ditangani manusia).

const MAX_HISTORY = 20;
const MODEL = 'claude-haiku-4-5-20251001';
const MAX_TOKENS = 500;
const HANDOFF_PAUSE_MINUTES = 30; // setelah ini bot aktif lagi otomatis

const PRODUCT_PATTERNS = [
  ['KitJelangNikah', /\b(nikah|menikah|pernikahan|wedding|kit jelang nikah|kitjelangnikah)\b/i],
  ['KarierKit', /\b(cv|karier|karir|lamaran kerja|ats|karierkit)\b/i],
  ['SalGlow', /\b(salglow|salep|glowing|flek|bekas jerawat|filo)\b/i],
];

// Kode ref dari landing page, contoh "KJN-7Q2MX". Prefix menentukan produk.
const REF_PATTERN = /\b(SG|KK|KJN)-([A-Z0-9]{5})\b/;
// Format LP terbaru: "#promo7Q2MX" -> ref PROMO7Q2MX (produk dari konteks/default).
const PROMO_PATTERN = /#PROMO([A-Z0-9]{5})\b/;
const REF_PRODUCTS = { SG: 'SalGlow', KK: 'KarierKit', KJN: 'KitJelangNikah' };

const CLOSING_PATTERNS = [
  /\bcod\b/i,
  /\b(sudah|udah|udh|sdh) (bayar|transfer|tf)\b/i,
  /\b(saya|aku|sy) (ambil|order|pesan|mau order)\b/i,
  /\boke? deal\b/i,
  /^\s*gas+\b/i,
  /\bbukti (transfer|tf)\b/i,
];

const MEDIA_LABELS = {
  image: '[Lead mengirim gambar]',
  video: '[Lead mengirim video]',
  audio: '[Lead mengirim voice note]',
  ptt: '[Lead mengirim voice note]',
  document: '[Lead mengirim dokumen]',
  sticker: '[Lead mengirim stiker]',
};

// Produk yang disebut eksplisit di pesan, atau null kalau tidak ada.
function detectProduct(text) {
  for (const [product, pattern] of PRODUCT_PATTERNS) {
    if (pattern.test(text)) return product;
  }
  return null;
}

function extractRef(text) {
  const upper = String(text || '').toUpperCase();
  const promo = upper.match(PROMO_PATTERN);
  if (promo) return { ref: 'PROMO' + promo[1], product: null };
  const m = upper.match(REF_PATTERN);
  return m ? { ref: m[0], product: REF_PRODUCTS[m[1]] } : null;
}

// Produk aktif: kode ref LP > produk yang disebut di pesan ini > produk tersimpan > default.
function resolveProduct(incoming, storedProduct) {
  const fromRef = extractRef(incoming);
  const mentioned = (fromRef && fromRef.product) || detectProduct(incoming);
  const product = mentioned || storedProduct || DEFAULT_PRODUCT;
  const switchedFrom = storedProduct && mentioned && mentioned !== storedProduct ? storedProduct : null;
  return { product, switchedFrom, ref: fromRef ? fromRef.ref : null };
}

function isClosingMessage(text) {
  return CLOSING_PATTERNS.some((p) => p.test(text));
}

function normalizeIncoming(body) {
  const text = String(body.message || '').trim();
  if (text) return text;
  return MEDIA_LABELS[body.messageType] || '[Lead mengirim pesan non-teks]';
}

function parseHistory(raw) {
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return [];
  }
}

// Claude butuh pesan pertama ber-role user dan role yang bergantian.
function trimHistory(history) {
  let trimmed = history.slice(-MAX_HISTORY);
  while (trimmed.length && trimmed[0].role !== 'user') trimmed = trimmed.slice(1);
  const merged = [];
  for (const msg of trimmed) {
    const last = merged[merged.length - 1];
    if (last && last.role === msg.role) last.content += '\n' + msg.content;
    else merged.push({ role: msg.role, content: msg.content });
  }
  return merged;
}

// Order terakhir lead kalau masih dalam jendela anti-dobel.
function recentOrder(row, now = Date.now()) {
  if (!row || !row.last_order_id || !row.last_order_at) return null;
  const age = now - new Date(row.last_order_at).getTime();
  return age >= 0 && age < SCALEV.duplicateOrderHours * 3600000 ? row.last_order_id : null;
}

// Kolom handoff berisi waktu bot dijeda (ISO). 'true' (format lama) = dijeda sampai diubah manual.
function isPaused(row, now = Date.now()) {
  const value = String((row && row.handoff) || '');
  if (value === 'true') return true;
  const at = Date.parse(value);
  return !Number.isNaN(at) && now - at < HANDOFF_PAUSE_MINUTES * 60000;
}

function prepareContext(body, row) {
  const incoming = normalizeIncoming(body);

  // Saat dijeda bot tidak membalas, tapi pesan lead tetap dicatat supaya
  // konteksnya tidak hilang ketika bot aktif lagi.
  if (isPaused(row)) {
    const kept = parseHistory(row.history).concat([{ role: 'user', content: incoming }]);
    return { paused: true, phone: body.phone, history: JSON.stringify(kept.slice(-MAX_HISTORY * 2)) };
  }

  const { product, switchedFrom, ref } = resolveProduct(incoming, row && row.active_product);
  const history = parseHistory(row && row.history);
  history.push({ role: 'user', content: incoming });
  const messages = trimHistory(history);

  // Order Scalev yang bisa di-update (PATCH): order lead (belum lengkap) atau order yang baru dibuat (revisi).
  const lastOrder = recentOrder(row);
  const scalevId = (row && row.scalev_id) || '';
  const patchId = scalevId && (!row.last_order_at || lastOrder) ? scalevId : '';

  const tools = orderTools(product);
  let system = buildSystemPrompt(product);
  if (tools) system += ' ' + ORDER_RULE;
  if (switchedFrom) {
    system += ` KONTEKS: Lead baru saja pindah topik dari ${switchedFrom} ke ${product}. Jawab tentang ${product}; jangan lanjut menawarkan ${switchedFrom} kecuali lead menanyakannya lagi.`;
  }

  return {
    phone: body.phone,
    name: body.pushName || '',
    incoming,
    active_product: product,
    switchedFrom,
    ref: ref || (row && row.ref) || '',
    isClosing: isClosingMessage(incoming),
    lastOrder,
    lastOrderId: (row && row.last_order_id) || '',
    patchId,
    isRevision: Boolean(patchId && lastOrder),
    // Lead baru: langsung dicatat di Scalev sebagai order berisi nama + nomor WA.
    newLead: !row,
    leadOrder: row ? null : {
      store_unique_id: SCALEV.storeUniqueId,
      customer_name: `${SCALEV.namePrefix || ''}${body.pushName || body.phone}`,
      customer_phone: body.phone,
      notes: 'Lead WA baru (belum order)',
    },
    messages,
    requestBody: {
      model: MODEL,
      max_tokens: MAX_TOKENS,
      system,
      messages,
      ...(tools ? { tools } : {}),
    },
  };
}

// Ambil teks balasan Claude, deteksi token handoff, rapikan format untuk WhatsApp.

const HANDOFF_TOKEN = '[HANDOFF]'; // bot dijeda sementara, CS manusia ambil alih
const INFO_TOKEN = '[INFO_ADMIN]'; // admin cukup dikabari, bot tetap lanjut jualan
const FALLBACK_REPLY =
  'Bentar ya kak, saya cek dulu ke atasan saya 🙏';

function toWhatsApp(text) {
  return text
    .replace(/\*\*(.+?)\*\*/g, '*$1*')
    .replace(/^#+\s*/gm, '')
    .trim();
}

function parseReply(response) {
  const block = response && Array.isArray(response.content)
    ? response.content.find((c) => c.type === 'text')
    : null;

  if (!block || !block.text) {
    const error = (response && response.error && response.error.message) || 'Respons Claude kosong';
    return { reply: FALLBACK_REPLY, needsHuman: true, apiError: error };
  }

  const needsHuman = block.text.includes(HANDOFF_TOKEN);
  const infoAdmin = block.text.includes(INFO_TOKEN);
  // [TESTIMONI] atau [TESTIMONI:flek,kusam]
  const testiMatch = block.text.match(/\[TESTIMONI(?::([a-z_,\s]+))?\]/i);
  const sendTestimoni = Boolean(testiMatch);
  const testimoniTopics = testiMatch && testiMatch[1]
    ? testiMatch[1].split(',').map((t) => t.trim().toLowerCase()).filter(Boolean)
    : [];
  const clean = [HANDOFF_TOKEN, INFO_TOKEN].reduce((t, tok) => t.split(tok).join(''), block.text)
    .replace(/\[TESTIMONI(?::[^\]]*)?\]/gi, '');
  // Balasan yang isinya hanya token testimoni tetap dijawab singkat, bukan pesan "sistem sibuk".
  const reply = toWhatsApp(clean) || (sendTestimoni ? 'Ini beberapa testimoni pembeli ya kak.' : '');
  return { reply: reply || FALLBACK_REPLY, needsHuman, infoAdmin, sendTestimoni, testimoniTopics, apiError: null };
}

// Follow-up otomatis untuk lead yang tidak membalas.
// Tahap FU dicatat di entri histori ({ role: 'assistant', fu: <tahap>, at: <ISO> }), tanpa kolom baru.

const FU_MINUTES = [60, 180, 360, 720, 1440, 2160]; // 1j, 3j, 6j, 12j, 24j, 36j
const FU_MAX_AGE_MINUTES = 48 * 60; // lead lebih lama dari ini tidak di-FU (juga saat pertama aktif)
const FU_QUIET_HOURS = [21, 7]; // jam WIB tanpa FU (21:00-06:59)
const FU_ORDER_DAYS = 14; // sudah order dalam 14 hari -> tidak di-FU

function wibHour(now) {
  return (new Date(now).getUTCHours() + 7) % 24;
}

// Tahap FU berikutnya yang jatuh tempo, atau null.
function dueFollowUp(row, now = Date.now()) {
  if (!row || !row.phone || isPaused(row, now)) return null;
  if (row.last_order_at && now - Date.parse(row.last_order_at) < FU_ORDER_DAYS * 86400000) return null;
  const [quietFrom, quietTo] = FU_QUIET_HOURS;
  const hour = wibHour(now);
  if (hour >= quietFrom || hour < quietTo) return null;

  const history = parseHistory(row.history);
  const last = history[history.length - 1];
  if (!last || last.role !== 'assistant') return null; // lead yang terakhir bicara -> bot yang harus jawab, bukan FU

  const lastChat = Date.parse(row.last_chat_at);
  if (Number.isNaN(lastChat)) return null;
  const elapsed = (now - lastChat) / 60000;
  if (elapsed < 0 || elapsed >= FU_MAX_AGE_MINUTES) return null;

  const sent = typeof last.fu === 'number' ? last.fu + 1 : 0; // jumlah FU yang sudah terkirim
  if (sent >= FU_MINUTES.length || elapsed < FU_MINUTES[sent]) return null;
  // Kalau beberapa tahap terlewat (mis. jam tenang), kirim satu saja: tahap terakhir yang sudah lewat.
  let stage = sent;
  while (stage + 1 < FU_MINUTES.length && elapsed >= FU_MINUTES[stage + 1]) stage++;
  return { stage, elapsedMinutes: Math.round(elapsed), previous: sent };
}

function waitLabel(minutes) {
  return minutes < 60 ? `${minutes} menit` : `${Math.round(minutes / 60)} jam`;
}

const FU_RULE =
  "FOLLOW-UP: Lead belum membalas chat terakhirmu. Tulis 1 pesan follow-up yang natural seperti CS manusia, singkat (maks 30 kata), dan BERBEDA dari semua pesanmu sebelumnya (jangan ulang kalimat/benefit yang sama). " +
  "Lihat pesan terakhir lead: kalau ada kendala (harga, ragu hasil, BPOM, kulit sensitif, ongkir, belum sempat, dll), follow-up menyentuh kendala itu dengan sudut pandang baru. " +
  "Kalau lead belum menyebut kendala apa pun, berikan 3-4 benefit Salep Glowing FILO dalam poin singkat (pilih yang belum pernah kamu sebut), lalu 1 pertanyaan ringan. " +
  "Kalau sebelumnya lead sedang mengisi data order, ingatkan pelan-pelan untuk melengkapi datanya. " +
  "Makin lama lead diam, makin ringan nadanya; jangan memaksa atau menagih. Tawarkan paket hanya kalau lead sebelumnya sudah menunjukkan minat beli. " +
  "Kalau lead sudah menolak tegas atau minta berhenti dihubungi, balas persis: SKIP";

function followUpRequest(row, due) {
  const product = row.active_product || DEFAULT_PRODUCT;
  const messages = trimHistory(parseHistory(row.history));
  messages.push({
    role: 'user',
    content: `[SISTEM, bukan dari lead] Lead belum membalas selama ${waitLabel(due.elapsedMinutes)}. Tulis follow-up ke-${due.stage + 1} dari ${FU_MINUTES.length}.`,
  });
  return {
    model: MODEL,
    max_tokens: 300,
    system: buildSystemPrompt(product) + ' ' + FU_RULE,
    messages,
  };
}

// Teks FU dari respons Claude, atau null kalau tidak perlu dikirim.
function followUpText(response) {
  const parsed = parseReply(response);
  if (parsed.apiError || parsed.needsHuman) return null;
  const text = parsed.reply.trim();
  if (!text || /^SKIP\b/i.test(text)) return null;
  return text;
}

function appendFollowUp(rawHistory, text, stage, now = Date.now()) {
  const history = parseHistory(rawHistory);
  history.push({ role: 'assistant', content: text, fu: stage, at: new Date(now).toISOString() });
  return JSON.stringify(history.slice(-MAX_HISTORY * 2));
}

const now = Date.now();
return $input.all().map((i) => i.json).filter((r) => r && r.phone).map((row) => {
  const due = dueFollowUp(row, now);
  return due ? { json: { phone: row.phone, stage: due.stage, history: row.history, requestBody: followUpRequest(row, due) } } : null;
}).filter(Boolean);

